int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n = 5;  // nodes 0-4
    vector<vector<pair<int, int>>> adj(n);  // adj[node] = list of {neighbor, weight}

    // Graph: 0-1(4), 0-2(1), 2-1(2), 2-3(5), 3-4(1), 1-4(3)
    adj[0] = {{1, 4}, {2, 1}};
    adj[1] = {{4, 3}};
    adj[2] = {{1, 2}, {3, 5}};
    adj[3] = {{4, 1}};

    vector<int> dist(n, INT_MAX);
    dist[0] = 0;

    // Min heap: (distance, node)
    priority_queue<pair<int, int>, vector<pair<int, int>>, greater<>> pq;
    pq.push({0, 0});

    while (!pq.empty()) {
        auto [d, u] = pq.top();
        pq.pop();
        if (d > dist[u]) continue;

        for (auto& [v, w] : adj[u]) {
            if (dist[u] + w < dist[v]) {
                dist[v] = dist[u] + w;
                pq.push({dist[v], v});
            }
        }
    }

    cout << "Shortest distances from 0:" << "\n";
    for (int i = 0; i < n; i++) {
        cout << "To " << i << ": " << dist[i] << "\n";
