// Manual GCD (iterative)
int gcd(int a, int b) {
    while (b) {
        int temp = b;
        b = a % b;
        a = temp;
    }
    return a;
}

// Recursive GCD
int gcdRec(int a, int b) {
    return b == 0 ? a : gcdRec(b, a % b);
}

