using namespace std;

const int MOD = 1e9 + 7;

// Pascal's triangle DP — O(n^2)
long long nCrDP(int n, int r) {
    vector<vector<long long>> C(n + 1, vector<long long>(r + 1, 0));
    for (int i = 0; i <= n; i++) {
        C[i][0] = 1;
        for (int j = 1; j <= min(i, r); j++) {
            C[i][j] = (C[i-1][j-1] + C[i-1][j]) % MOD;
        }
    }
    return C[n][r];
}

// Factorial precomputation — O(n) precompute, O(1) query
const int MAXN = 1e6 + 5;
long long fact[MAXN], invFact[MAXN];

long long modPow(long long a, long long e) {
    long long res = 1;
    while (e) {
        if (e & 1) res = res * a % MOD;
        a = a * a % MOD;
        e >>= 1;
    }
    return res;
}

void precomputeFactorials() {
    fact[0] = 1;
    for (int i = 1; i < MAXN; i++) fact[i] = fact[i-1] * i % MOD;
    invFact[MAXN-1] = modPow(fact[MAXN-1], MOD-2);
    for (int i = MAXN-2; i >= 0; i--) invFact[i] = invFact[i+1] * (i+1) % MOD;
}

long long nCrFast(int n, int r) {
    if (r < 0 || r > n) return 0;
    return fact[n] * invFact[r] % MOD * invFact[n-r] % MOD;
}

// Multiplicative formula for single large nCr
long long nCrMultiplicative(long long n, long long r) {
    if (r > n - r) r = n - r;
    long long num = 1, den = 1;
    for (long long i = 0; i < r; i++) {
        num = num * (n - i) % MOD;
        den = den * (i + 1) % MOD;
    }
    return num * modPow(den, MOD-2) % MOD;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cout << "C(10, 3) DP: " << nCrDP(10, 3) << "\n";

    precomputeFactorials();
    cout << "C(1000, 500) fast: " << nCrFast(1000, 500) << "\n";
    cout << "C(1e9, 5) multiplicative: " << nCrMultiplicative(1000000000, 5) << "\n";

    return 0;
}

