#include <bits/stdc++.h>
using namespace std;

const int MAXN = 1e7 + 5;
vector<char> is_prime;
vector<int> primes;

void sieve(int n) {
    is_prime.assign(n + 1, true);
    is_prime[0] = is_prime[1] = false;

    for (int i = 2; i * i <= n; i++) {
        if (is_prime[i]) {
            for (int j = i * i; j <= n; j += i) {
                is_prime[j] = false;
            }
        }
    }

    for (int i = 2; i <= n; i++) {
        if (is_prime[i]) primes.push_back(i);
    }
}

// Linear sieve (Euler's sieve) — O(n)
void linearSieve(int n) {
    vector<int> lp(n + 1);  // lowest prime factor
    for (int i = 2; i <= n; i++) {
        if (lp[i] == 0) {
            lp[i] = i;
            primes.push_back(i);
        }
        for (int p : primes) {
            if (p > lp[i] || 1LL * i * p > n) break;
            lp[i * p] = p;
        }
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n = 50;
    sieve(n);

    cout << "Primes up to " << n << ": ";
    for (int p : primes) cout << p << " ";
    cout << "\nCount: " << primes.size() << "\n";

    // Check if 47 is prime
    cout << "Is 47 prime? " << (is_prime[47] ? "YES" : "NO") << "\n";

    return 0;
}

