// Optimized sieve — only odd numbers
vector<int> optimizedSieve(int n) {
    vector<bool> is_prime(n + 1, true);
    is_prime[0] = is_prime[1] = false;

    for (int i = 3; i * i <= n; i += 2) {
        if (is_prime[i]) {
            for (int j = i * i; j <= n; j += 2 * i) {
                is_prime[j] = false;
            }
        }
    }

    vector<int> primes = {2};
    for (int i = 3; i <= n; i += 2) {
        if (is_prime[i]) primes.push_back(i);
    }
    return primes;
}

