#include <bits/stdc++.h>
using namespace std;

vector<char> segmentedSieve(long long L, long long R) {
    long long lim = sqrt(R);
    vector<char> mark(lim + 1, true);
    vector<long long> primes;

    // Generate base primes up to sqrt(R)
    for (long long i = 2; i <= lim; i++) {
        if (mark[i]) {
            primes.push_back(i);
            for (long long j = i * i; j <= lim; j += i) {
                mark[j] = false;
            }
        }
    }

    // Process segments
    const int S = 100000;  // segment size
    vector<char> isPrime(R - L + 1, true);

    for (long long p : primes) {
        long long start = max(p * p, (L + p - 1) / p * p);
        for (long long j = start; j <= R; j += p) {
            isPrime[j - L] = false;
        }
    }

    if (L == 1) isPrime[0] = false;

    return isPrime;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long L = 1e12, R = 1e12 + 1000;
    auto isPrime = segmentedSieve(L, R);

    cout << "Primes in range [" << L << ", " << R << "]: ";
    int count = 0;
    for (int i = 0; i <= R - L; i++) {
        if (isPrime[i]) {
            cout << (L + i) << " ";
            count++;
        }
    }
    cout << "\nCount: " << count << "\n";

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

const int MAXN = 1e7;
vector<char> is_prime;
vector<int> primeCount;  // prefix sum

void buildPrefix() {
    is_prime.assign(MAXN + 1, true);
    is_prime[0] = is_prime[1] = false;

    for (int i = 2; i * i <= MAXN; i++) {
        if (is_prime[i]) {
            for (int j = i * i; j <= MAXN; j += i) {
                is_prime[j] = false;
            }
        }
    }

    primeCount.resize(MAXN + 1);
    for (int i = 1; i <= MAXN; i++) {
        primeCount[i] = primeCount[i-1] + (is_prime[i] ? 1 : 0);
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    buildPrefix();

    int q;
    cin >> q;
    while (q--) {
        int L, R;
        cin >> L >> R;
        cout << primeCount[R] - primeCount[L-1] << "\n";
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

const int MAXN = 1e6;

int spf[MAXN + 1];        // smallest prime factor
int phi[MAXN + 1];        // Euler's totient
int mobius[MAXN + 1];     // Mobius function
int numDiv[MAXN + 1];     // number of divisors
long long sumDiv[MAXN + 1]; // sum of divisors

void sieveApplications() {
    for (int i = 1; i <= MAXN; i++) {
        spf[i] = i;
        phi[i] = i;
        mobius[i] = 1;
        numDiv[i] = 1;
        sumDiv[i] = 1;
    }

    for (int i = 2; i <= MAXN; i++) {
        if (spf[i] == i) {  // i is prime
            for (int j = i; j <= MAXN; j += i) {
                if (spf[j] == j) spf[j] = i;

                // Totient
                phi[j] -= phi[j] / i;

                // Mobius
                int cnt = 0, x = j;
                while (x % i == 0) { x /= i; cnt++; }
                if (cnt > 1) mobius[j] = 0;
                else if (cnt == 1) mobius[j] *= -1;
            }
        }
    }

    // Number of divisors and sum of divisors
    for (int i = 1; i <= MAXN; i++) {
        for (int j = i; j <= MAXN; j += i) {
            numDiv[j]++;
            sumDiv[j] += i;
        }
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    sieveApplications();

    int n = 12;
    cout << "SPF of " << n << ": " << spf[n] << "\n";
    cout << "Phi(" << n << "): " << phi[n] << "\n";
    cout << "Mobius(" << n << "): " << mobius[n] << "\n";
    cout << "NumDiv(" << n << "): " << numDiv[n] << "\n";
    cout << "SumDiv(" << n << "): " << sumDiv[n] << "\n";

    return 0;
}
